using System;
using UnityEngine;
namespace Hakaton.Demo.Investigation
{
    [Serializable] public sealed class CaseClue
    {
        public string id,title,text,place;
        public CaseClue(string i,string t,string b,string p){id=i;title=t;text=b;place=p;}
    }
    public static class CaseCatalog
    {
        public static readonly CaseClue[] Clues={
            new CaseClue("E01","Схема четырёх фигурок","На листе изображён механизм с четырьмя гнёздами и фигурки X, Y, Z, K. Одну такую я помню у себя. Стоит показать схему братьям.","Кабинет отца"),
            new CaseClue("E02","Следы на ковре","Отпечатки подошвы. Ни у меня, ни у братьев такой обуви нет. Кто-то чужой был в кабинете. Когда — пока непонятно.","Кабинет отца"),
            new CaseClue("E03","Пустая бутылка «Берёзка»","Пустая бутылка водки. Этикетка сорвана, название ещё можно разобрать. Отец обычно не пил такое. Пока больше ничего.","Кабинет отца"),
            new CaseClue("E04","Дело Фёдора · 1997","В доступной копии дела указан 1997 год. Официальная версия — несчастный случай. Тело обнаружено в доме; рядом лежал пистолет. Я помню, что отца не стало три года назад.","Архив участка"),
            new CaseClue("E05","Опись оружия · .45","Пистолет отца, найденный рядом с телом. Штатный калибр — .45 ACP (11,43×23 мм). Оружие опечатано; переоборудование ствола не отмечено.","Архив участка"),
            new CaseClue("E06","Экспертиза · 9 мм","Из головы Фёдора извлечена пуля калибра 9×19 мм. Это отдельное заключение, приложенное к делу.","Архив участка"),
            new CaseClue("E07","Похожее закрытое дело","Подозреваемый утверждал, что ничего не помнит. Мотив не установлен. Дело закрыто. Подтверждённой связи с делом отца в материалах нет.","Архив участка"),
            new CaseClue("E08","Гильза из старой куртки","Гильза в кармане моей старой куртки. Опять после стрельбища карманы не вытряхнул. Заберу с собой.","Дом Алексея"),
            new CaseClue("E09","Старое письмо","«Лёша, приезжай. Нужно кое-что обсудить. Лучше сегодня». Похоже на письмо от отца. Сохранилось среди моих бумаг.","Дом Алексея"),
            new CaseClue("E10","Документ · 2000","Документ из хранилища относится к смерти Фёдора в 2000 году. Дата не совпадает с копией дела и тем, что я помню.","Хранилище"),
            new CaseClue("E11","Папка Фёдора и запись","Личные записи о закрытой программе. Отдельный лист связывает Алексея с операцией и обработкой корреспонденции. Рядом — магнитофонная запись Фёдора. Нужно прослушать её целиком.","Хранилище"),
            new CaseClue("E12","Кассеты наблюдения","Фрагмент записи из дома. Видны чужие ботинки и край пальто, лица нет. Есть события, которых я не помню. Время записи надёжно установить нельзя.","Тайная комната"),
            new CaseClue("E13","Семейная фотография","Отец и трое сыновей у крыльца. Дмитрий щурится от солнца. Можно показать Ивану.","Гостиная")
        };
        public static readonly string[,] Recipes={
            {"D01_CALIBER_MISMATCH","E05","E06","Разные калибры","Странно. Пистолет один, а калибр пули другой. Как это вообще прошло мимо следствия?"},
            {"D02_SIMILAR_CASE_PATTERN","E07","D01_CALIBER_MISMATCH","Похожие дела? · гипотеза","В одном деле человек ничего не помнит. В другом даже оружие с пулей не сходится. И оба дела закрыты. Совпадение?"},
            {"D03_ALEX_CALIBER","D01_CALIBER_MISMATCH","E08","Мой калибр","Мой калибр.\nУ него другой…"},
            {"D04_DATE_CONTRADICTION","E04","E10","Дата не сходится","В деле — 1997. Здесь — 2000. Нужно позвонить напарнику."},
            {"D05_LETTER_OPERATION","E09","E11","Письмо и операция","Письмо может быть связано с операцией из бумаг отца. Кто его отправил — пока неизвестно."},
            {"D06_UNKNOWN_VISITOR","E02","E12","Неизвестный посетитель · гипотеза","Отец за кем-то следил. В кабинете были чужие следы. На записи — кто-то посторонний. Кто и когда — ещё надо выяснить."}
        };
        public static CaseClue Find(string id)=>Array.Find(Clues,c=>c.id==id);
        public static int Recipe(string id){for(int i=0;i<Recipes.GetLength(0);i++)if(Recipes[i,0]==id)return i;return -1;}
        public static string Title(string id){var c=Find(id);int r=Recipe(id);return c!=null?c.title:r>=0?Recipes[r,3]:id;}
        public static string Body(string id){var c=Find(id);int r=Recipe(id);if(id=="E01"){var solution=Resources.Load<FigurineSolution>("FigurineSolution");if(solution!=null&&solution.Valid)return c.text+"\n\nГнёзда на схеме слева направо: "+string.Join("  ·  ",solution.leftToRight);}
            return c!=null?c.text:r>=0?Recipes[r,4]:"";}
    }
}
